// All prompts and responses concerned a synthetic business; no customer data.
import zlib from 'node:zlib';
import crypto from 'node:crypto';
const archived="";
export function readPriorMixedProviderOutputs(){
 const bytes=zlib.gunzipSync(Buffer.from(archived,'base64'));
 const digest=crypto.createHash('sha256').update(bytes).digest('hex');
 if(digest!=='38cdaa22a5e2d82ef2fa6a6c1f018ba8bda8a0be2049674ddb963161286d6820')
   throw Error('ARCHIVED_LIVE_OUTPUT_INTEGRITY_MISMATCH');
 const parsed=JSON.parse(bytes.toString('utf8'));
 if(parsed.rows.length!==25||parsed.rows.some((r,i)=>r.turn!==i+1||typeof r.text!=='string'))
   throw Error('ARCHIVED_LIVE_OUTPUT_INCOMPLETE');
 return parsed;
}
